const { useEffect, useRef, useState } = React;

// 画布框架：按 DPR 设置像素尺寸、跟随宽度重绘、切换主题时重绘；坐标单位为 CSS 像素
const useCanvas = (draw, deps) => {
  const ref = useRef(null);
  const { color } = useTokens();
  // 重绘函数每次渲染更新，尺寸监听只建立一次，动画逐帧重绘时不重复创建观察器
  const renderRef = useRef(() => {});
  renderRef.current = () => {
    const canvas = ref.current;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !ctx) return;
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = canvas.getBoundingClientRect();
    const pixelWidth = Math.round(width * dpr);
    const pixelHeight = Math.round(height * dpr);
    // 重设尺寸会清空并重新分配画布，只在尺寸真正变化时才做
    if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
      canvas.width = pixelWidth;
      canvas.height = pixelHeight;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, width, height);
    ctx.save();
    draw(ctx, { width, height, dpr, color });
    ctx.restore();
  };
  useEffect(() => renderRef.current(), [color, ...deps]);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const observer = new ResizeObserver(() => renderRef.current());
    observer.observe(canvas);
    return () => observer.disconnect();
  }, []);
  return ref;
};

// 画布上的标注文字：等宽字体、次要墨色
const note = (ctx, color, text, x, y, align = "left") => {
  ctx.save();
  ctx.font = `12px ${color("font-mono")}`;
  ctx.fillStyle = color("ink-3");
  ctx.textAlign = align;
  ctx.textBaseline = "middle";
  ctx.fillText(text, x, y);
  ctx.restore();
};

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 20px 20px;
      background-position: 10px 10px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Stage = ({ canvasRef, height, className = "" }) => (
  <canvas
    ref={canvasRef}
    className={`cb-grid block w-full rounded-tau-md border border-line-1 ${className}`}
    style={{ height }}
  />
);

const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-[220px] flex-1 items-center gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{format(value)}</span>
  </label>
);

const Demo = ({ children }) => (
  <div className="flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    {children}
  </div>
);

const Row = ({ children }) => <div className="flex flex-wrap items-center gap-x-6 gap-y-3">{children}</div>;

const OPERATIONS = [
  "source-over", "source-in", "source-out", "source-atop",
  "destination-over", "destination-in", "destination-out", "destination-atop",
  "lighter", "copy", "xor", "multiply", "screen", "overlay", "darken", "lighten",
  "color-dodge", "color-burn", "hard-light", "soft-light", "difference", "exclusion",
  "hue", "saturation", "color", "luminosity",
];

const Component = () => {
  const [operation, setOperation] = useState("destination-over");
  const ref = useCanvas((ctx, { color }) => {
    // 先画的方块是 destination，后画的圆是 source
    ctx.fillStyle = color("tag-2");
    ctx.fillRect(50, 30, 160, 160);
    ctx.globalCompositeOperation = operation;
    ctx.fillStyle = color("tag-4");
    ctx.beginPath();
    ctx.arc(210, 110, 80, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalCompositeOperation = "source-over";
    note(ctx, color, "方块：destination（先画）", 320, 90);
    note(ctx, color, "圆：source（后画）", 320, 114);
  }, [operation]);

  return (
    <Demo>
      <Stage canvasRef={ref} height={220} />
      <Row>
        <ui.Select
          size="sm"
          aria-label="globalCompositeOperation"
          options={OPERATIONS.map(value => ({ value, label: value }))}
          value={operation}
          onValueChange={setOperation}
          className="w-[220px]"
        />
        <Chip>ctx.globalCompositeOperation = "{operation}"</Chip>
      </Row>
    </Demo>
  );
};
